CREATE TABLE `tenant_automations` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `public_id` CHAR(36) NOT NULL, `tenant_id` BIGINT UNSIGNED NOT NULL, `trigger` ENUM('APPOINTMENT_REMINDER','POST_APPOINTMENT','INACTIVE_CUSTOMER','CUSTOMER_BIRTHDAY') NOT NULL, `active` BOOLEAN NOT NULL DEFAULT TRUE, `offset_minutes` INT NOT NULL DEFAULT 0, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `tenant_automations_public_id_key` (`public_id`), UNIQUE INDEX `tenant_automations_tenant_id_trigger_key` (`tenant_id`,`trigger`), INDEX `tenant_automations_tenant_id_active_idx` (`tenant_id`,`active`), CONSTRAINT `tenant_automations_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `automation_executions` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `public_id` CHAR(36) NOT NULL, `tenant_id` BIGINT UNSIGNED NOT NULL, `automation_id` BIGINT UNSIGNED NOT NULL, `target_type` VARCHAR(80) NOT NULL, `target_public_id` CHAR(36) NOT NULL, `status` ENUM('SENT','SKIPPED','FAILED') NOT NULL, `error` VARCHAR(500) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `automation_executions_public_id_key` (`public_id`), UNIQUE INDEX `automation_executions_automation_target_key` (`automation_id`,`target_type`,`target_public_id`), INDEX `automation_executions_tenant_id_created_at_idx` (`tenant_id`,`created_at`), CONSTRAINT `automation_executions_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `automation_executions_automation_id_fkey` FOREIGN KEY (`automation_id`) REFERENCES `tenant_automations`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
